import Foundation
import NIO
import NIOConcurrencyHelpers

// MARK: - Rate Limiter
actor RateLimiter {
    private var buckets: [String: TokenBucket] = [:]
    private let maxTokens: Int
    private let refillRate: Double
    private let windowSeconds: TimeInterval

    struct TokenBucket {
        var tokens: Int
        var lastRefill: Date
        var windowStart: Date
        var requestsInWindow: Int
    }

    init(maxTokens: Int = 10, refillRate: Double = 1.0, windowSeconds: TimeInterval = 60) {
        self.maxTokens = maxTokens
        self.refillRate = refillRate
        self.windowSeconds = windowSeconds
    }

    func shouldAllow(clientId: String) -> Bool {
        let now = Date()

        if var bucket = buckets[clientId] {
            // Refill tokens based on elapsed time
            let elapsed = now.timeIntervalSince(bucket.lastRefill)
            let newTokens = Int(elapsed * refillRate)
            bucket.tokens = min(maxTokens, bucket.tokens + newTokens)
            bucket.lastRefill = now

            // Check sliding window
            if now.timeIntervalSince(bucket.windowStart) >= windowSeconds {
                bucket.windowStart = now
                bucket.requestsInWindow = 0
            }

            if bucket.tokens > 0 && bucket.requestsInWindow < maxTokens {
                bucket.tokens -= 1
                bucket.requestsInWindow += 1
                buckets[clientId] = bucket
                return true
            }

            buckets[clientId] = bucket
            return false
        } else {
            buckets[clientId] = TokenBucket(
                tokens: maxTokens - 1,
                lastRefill: now,
                windowStart: now,
                requestsInWindow: 1
            )
            return true
        }
    }
}

// MARK: - Message Router
actor MessageRouter {
    private var channels: [String: [String]] = [:]
    private let rateLimiter: RateLimiter

    init(rateLimiter: RateLimiter) {
        self.rateLimiter = rateLimiter
    }

    func subscribe(clientId: String, channel: String) {
        channels[channel, default: []].append(clientId)
    }

    func route(message: ChatMessage) async -> RouteResult {
        let recipients = channels[message.channel] ?? []
        return .delivered(to: recipients)
    }
}

// MARK: - Chat Server
actor ChatServer {
    private let router: MessageRouter
    private let rateLimiter: RateLimiter
    private var connections: [String: ClientConnection] = [:]

    init() {
        let limiter = RateLimiter(maxTokens: 10, refillRate: 1.0, windowSeconds: 60)
        self.rateLimiter = limiter
        self.router = MessageRouter(rateLimiter: limiter)
    }

    func handleConnection(clientId: String, conn: ClientConnection) {
        connections[clientId] = conn
    }

    func handleMessage(raw: Data, from clientId: String) async -> SendResult {
        guard let message = try? JSONDecoder().decode(ChatMessage.self, from: raw) else {
            return .error("Invalid message format")
        }

        // Pre-check: verify sender matches connection
        guard message.senderId == clientId else {
            return .error("Sender mismatch")
        }

        // Apply rate limiting at the connection level
        let connectionAllowed = await rateLimiter.shouldAllow(clientId: clientId)
        guard connectionAllowed else {
            return .rateLimited
        }

        // Route the message
        let result = await router.route(message: message)
        switch result {
        case .delivered(let recipients):
            await broadcast(message: message, to: recipients)
            return .sent
        case .rateLimited:
            return .rateLimited
        }
    }

    private func broadcast(message: ChatMessage, to recipients: [String]) async {
        for recipientId in recipients {
            if let conn = connections[recipientId] {
                await conn.send(message: message)
            }
        }
    }
}

// MARK: - Models
struct ChatMessage: Codable {
    let senderId: String
    let channel: String
    let content: String
    let timestamp: Date
}

enum RouteResult {
    case delivered(to: [String])
    case rateLimited
}

enum SendResult {
    case sent
    case rateLimited
    case error(String)
}

protocol ClientConnection: Actor {
    func send(message: ChatMessage) async
}
